window.SUBJECT_DATA = window.SUBJECT_DATA || {};
window.SUBJECT_DATA["antoxi"] = window.SUBJECT_DATA["antoxi"] || { sections: [], groups: [], exercises: [] };
window.SUBJECT_DATA["antoxi"].sections.push({
  "slug": "ch03-sfalmata-kai-dieykriniseis",
  "num": "3.7",
  "title": "Βασικά Σημεία Προσοχής & Σύνοψη SOS",
  "kicker": "Επισημάνσεις & SOS",
  "lead": "Κρίσιμες επισημάνσεις για τη θεωρία, συνηθέστερες παρανοήσεις των μαθητών και πρακτικές συμβουλές επιτυχίας στις εξετάσεις.",
  "blocks": [
    {
      "type": "h",
      "text": "1. Ουσιαστικές Διευκρινίσεις & Σημεία SOS για τις Εξετάσεις"
    },
    {
      "type": "p",
      "text": "Στο Κεφάλαιο 3 εξετάζουμε τη σύνθεση και την ανάλυση δυνάμεων, καθώς και τις συνθήκες ισορροπίας στερεού σώματος. Για την άψογη επίλυση των θεμάτων, οι μαθητές πρέπει να προσέξουν ιδιαίτερα τα παρακάτω σημεία:"
    },
    {
      "type": "ul",
      "items": [
        "Προσοχή στα πρόσημα στις συνιστώσες: Κατά την αναλυτική μέθοδο εύρεσης της συνισταμένης πολλών ομοεπιπέδων δυνάμεων, οι προβολές στους άξονες \\(Ox\\) και \\(O\\psi\\) λαμβάνουν αλγεβρικό πρόσημο (+ ή -) ανάλογα με τη φορά τους.",
        "Ορθή χρήση τριγωνομετρικών αριθμών: Θυμηθείτε ότι για γωνίες \\(30^\\circ\\), \\(45^\\circ\\) και \\(60^\\circ\\) χρησιμοποιούμε πάντα τις ακριβείς τιμές (π.χ. \\(\\text{ημ}30^\\circ = 0{,}5\\), \\(\\text{συν}30^\\circ = \\frac{\\sqrt{3}}{2} \\approx 0{,}866\\)).",
        "Συνθήκες ισορροπίας στερεού σώματος: Ένα στερεό σώμα ισορροπεί όταν μηδενίζονται τόσο το αλγεβρικό άθροισμα των δυνάμεων όσο και το αλγεβρικό άθροισμα των ροπών ως προς οποιοδήποτε σημείο: \\(\\Sigma F = 0\\) και \\(\\Sigma M = 0\\)."
      ]
    },
    {
      "type": "callout",
      "kind": "warning",
      "title": "Σημαντική Διευκρίνιση - Τυπογραφικό Σχολικού Βιβλίου",
      "text": "Στις ασκήσεις ανάλυσης δύναμης σε δύο παράλληλες συνιστώσες (π.χ. § 3.8), ενδέχεται να συναντήσετε τυπογραφικές αποκλίσεις στις τιμές αποστάσεων (όπως \\(l_2 = 50\\text{ cm}\\) αντί για \\(40\\text{ cm}\\)). Στις εξετάσεις ακολουθούμε πάντα πιστά τα δεδομένα της εκφώνησης του θέματος που δίνεται."
    },
    {
      "type": "h",
      "text": "2. Συνοπτικό Τυπολόγιο Κεφαλαίου 3"
    },
    {
      "type": "formula",
      "html": "\\[\\begin{aligned} \\Sigma &= F_1 + F_2 \\quad \\text{(Συγγραμμικές - Ομόρροπες)} \\\\ \\Sigma &= F_1 - F_2 \\quad \\text{(Συγγραμμικές - Αντίρροπες)} \\\\ \\Sigma &= \\sqrt{F_1^2 + F_2^2} \\quad (\\varphi = 90^\\circ) \\\\ \\varepsilon\\varphi\\theta &= \\frac{F_2}{F_1} \\quad \\text{(Διεύθυνση συνισταμένης υπό } 90^\\circ) \\end{aligned} \\]",
      "caption": "Βασικοί τύποι σύνθεσης δυνάμεων."
    },
    {
      "type": "formula",
      "html": "\\[\\begin{aligned} \\Sigma_x &= \\Sigma F_x = F_{1x} + F_{2x} - F_{3x} \\\\ \\Sigma_\\psi &= \\Sigma F_\\psi = F_{1\\psi} - F_{2\\psi} + F_{3\\psi} \\\\ \\Sigma &= \\sqrt{(\\Sigma F_x)^2 + (~\\Sigma F_\\psi)^2} \\\\ \\varepsilon\\varphi\\theta &= \\frac{\\Sigma F_\\psi}{\\Sigma F_x} \\end{aligned} \\]",
      "caption": "Αναλυτική μέθοδος για πολλές ομοεπίπεδες δυνάμεις."
    },
    {
      "type": "callout",
      "kind": "tip",
      "title": "Χρυσός Κανόνας Επιτυχίας",
      "text": "Πριν ξεκινήσετε οποιονδήποτε υπολογισμό σε άσκηση μηχανικής, κάντε πάντα ένα καθαρό πρόχειρο σχήμα ελεύθερου σώματος (ΔΕΣ), σημειώνοντας τα σημεία εφαρμογής, τα βέλη των δυνάμεων και το επιλεγμένο σύστημα αξόνων."
    }
  ]
});
;

